const list = {
  head: null,
  tail: null,
  size: 0,
  pushBack(value) {
    const node = { value, next: null };
    if (this.tail === null) this.head = node;
    else this.tail.next = node;
    this.tail = node;
    this.size++;
  },
  popFront() {
    const node = this.head;
    this.head = node.next;
    if (this.head === null) this.tail = null;
    this.size--;
    return node.value;
  },
};

