class LRU {
  #map = new Map();
  constructor(capacity) {
    this.capacity = capacity;
  }
  get(key) {
    if (!this.#map.has(key)) return undefined;
    const value = this.#map.get(key);
    this.#map.delete(key);
    this.#map.set(key, value);
    return value;
  }
  set(key, value) {
    this.#map.delete(key);
    this.#map.set(key, value);
    if (this.#map.size > this.capacity) this.#map.delete(this.#map.keys().next().value);
  }
  keys() {
    return [...this.#map.keys()];
  }
}

const prices = new LRU(2);
prices.set("RICE", 850000);
prices.set("OIL", 240000);
prices.get("RICE");
prices.set("SALT", 30000);
console.log(prices.keys(), prices.get("OIL"), prices.get("RICE"));

